// Tests part (b): dispatch from dispatch.s, on its own.
//
// my_write, my_exit and weighted_avg below are stand-ins written in C. They
// print each call, so the output shows what dispatch called and with which
// arguments. This way part (b) does not depend on your parts (a) and (c).
//
// Input: n, then n lines "marks credits".
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

void dispatch(unsigned long *marks, unsigned long *credits, unsigned long n);

static unsigned long marks[1000], credits[1000];

__attribute__((force_align_arg_pointer))
long my_write(const char *buf, unsigned long len) {
    printf("my_write(\"");
    for (unsigned long i = 0; i < len; i++)
        if (buf[i] == '\n') printf("\\n");
        else putchar(buf[i]);
    printf("\", %lu)\n", len);
    fflush(stdout);
    return (long)len;
}

__attribute__((force_align_arg_pointer))
void my_exit(long code) {
    printf("my_exit(%ld)\n", code);
    fflush(stdout);
    _exit((int)code);
}

__attribute__((force_align_arg_pointer))
unsigned long weighted_avg(unsigned long *m, unsigned long *c, unsigned long n) {
    printf("weighted_avg(%s, %s, %lu)\n", m == marks ? "marks" : "WRONG POINTER",
           c == credits ? "credits" : "WRONG POINTER", n);
    return 10 + 7 * n;   // any value; dispatch must pass it on to my_exit
}

int main(void) {
    unsigned long n;
    if (scanf("%lu", &n) != 1 || n > 1000) return 1;
    for (unsigned long i = 0; i < n; i++)
        if (scanf("%lu %lu", &marks[i], &credits[i]) != 2) return 1;
    dispatch(marks, credits, n);
    printf("ERROR: dispatch returned\n");
    return 0;
}
